"""What the port scripts share: the upstream folder argument, the generated files' header and the check that a
generated file names no product, brand or upstream project (only the licence notice credits the author)."""
import os
import re
import subprocess
import sys

USINA = os.path.normpath(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..'))

# The shared utilities' names, for every port (after its patches; order matters: the specific ones first).
DSPUTIL_GENERIC = [
    ('#include "stmlib/stmlib.h"', '#include "port/dsputil/dsputil.h"'),
    ('STMLIB_STMLIB_H_', 'USINA_DSPUTIL_DSPUTIL_H_'),
    ('#include "stmlib/', '#include "port/dsputil/'),
    ('using namespace stmlib;', 'using namespace usina_dsputil;'),
    ('namespace stmlib {', 'namespace usina_dsputil {'),
    ('// namespace stmlib', '// namespace usina_dsputil'),
    ('stmlib::', 'usina_dsputil::'),
    ('STMLIB_', 'USINA_DSPUTIL_'),
]

# Anywhere in the text: the upstream projects' names and what the code must not keep.
BANNED_ANYWHERE = re.compile(r'Mutable|[Ee]urorack|[Pp]laits|PLAITS|[Cc]louds|CLOUDS|[Bb]eads|BEADS|[Ss]tmlib|STMLIB'
                             r'|[Pp]arasites|pichenettes|[Vv]actrol|__attribute__|__asm|debug_pin')
# In comments only (numbers in tables may be these digits): products and modules.
BANNED_IN_COMMENTS = re.compile(r'\b(808|909|DX7|DX-7|Braids|Rings|Elements|Shruthi|Ambika|SAM)\b')
COMMENT = re.compile(r'//[^\n]*|/\*.*?\*/', re.S)


def upstream_dir(usage):
    """The read-only upstream clones' folder: a required argument."""
    if len(sys.argv) < 2:
        sys.exit('usage: ' + usage)
    return sys.argv[1]


def git_head(path):
    try:
        return subprocess.check_output(['git', '-C', path, 'rev-parse', '--short', 'HEAD'], text=True).strip()
    except Exception:
        return '?'


def header(script):
    return ('// Generated by tools/port/%s: do not edit; edit the script (its PATCHES list each change and why).\n'
            '// MIT: the notice below. Provenance: THIRD_PARTY.md.\n' % script)


def check_names(name, text):
    m = BANNED_ANYWHERE.search(text)
    if m:
        sys.exit('%s still has "%s"' % (name, m.group(0)))
    for c in COMMENT.finditer(text):
        m = BANNED_IN_COMMENTS.search(c.group(0))
        if m:
            sys.exit('%s still has "%s" in a comment: %s' % (name, m.group(0), c.group(0)[:120]))


def apply_patches(key, text, patches, used):
    for i, (f, old, new, times, why) in enumerate(patches):
        if f != key:
            continue
        if isinstance(old, re.Pattern):
            text, n = old.subn(new.replace('\\', '\\\\'), text)
        else:
            n = text.count(old)
            text = text.replace(old, new)
        if n != times:
            sys.exit('patch %d (%s) matched %d times, not %d: %s' % (i, f, n, times, why))
        used[i] += 1
    return text


def check_all_used(used):
    unused = [i for i, n in used.items() if n == 0]
    if unused:
        sys.exit('patches never applied: %s' % unused)


def write(out_dir, rel, script, text):
    dst = os.path.join(out_dir, rel)
    os.makedirs(os.path.dirname(dst), exist_ok=True)
    with open(dst, 'w', encoding='utf-8', newline='\n') as fh:
        fh.write(header(script) + text)
